<h1 class="h3 mb-3">注册子域名</h1><div class="card"><div class="card-body"><p>根域名：<b><?= h($domain['domain']) ?></b>；价格：<b><?= (float)$domain['price'] > 0 ? money($domain['price']) : '免费' ?></b></p><?php if ($availableCount !== -1): ?><p class="small <?= $availableCount ? 'text-muted' : 'text-danger' ?>"><?= $availableCount ? '剩余 ' . (int)$availableCount : '已售罄' ?></p><?php endif; ?><form method="post" data-coupon-form data-coupon-type="dns_sub_new" data-coupon-url="<?= h(url_to('index/order/coupon_preview')) ?>"><?= csrf_field() ?><input type="hidden" name="domain_id" value="<?= (int)$domain['id'] ?>"><label class="form-label">前缀</label><div class="input-group mb-2"><input class="form-control" id="prefix" name="prefix" required minlength="<?= h($domain['min_len']) ?>" maxlength="<?= h($domain['max_len']) ?>"><span class="input-group-text">.<?= h($domain['domain']) ?></span></div><div id="availability" class="form-text mb-3">输入前缀后离开输入框查询可用性。</div><?php if ((float)$domain['price'] > 0) {
    include __DIR__ . '/../_coupon.php';
} ?><button class="btn btn-primary" <?= $availableCount === 0 ? 'disabled' : '' ?>><?= $availableCount === 0 ? '已售罄' : ((float)$domain['price'] > 0 ? '生成订单并支付' : '免费注册') ?></button></form></div></div><script>document.getElementById('prefix').onblur=function(){var p=this,o=document.getElementById('availability');fetch('<?= h(url_to('index/dns/check', ['domain_id' => $domain['id']])) ?>&prefix='+encodeURIComponent(p.value)).then(function(r){return r.json()}).then(function(x){o.textContent=x.code===0?'可用：'+x.data.fqdn:x.msg;o.className='form-text mb-3 '+(x.code===0?'text-success':'text-danger')});};</script>
